#ifndef CH_READONLY_RESULT_GATE_H
#define CH_READONLY_RESULT_GATE_H
#include "../platform/platform.h"

/* This observes generated bytes. It neither executes nor certifies manual
 * prediction timing. A completed result never sets hardware_verified. */
#define CH_RESULT_ABI 4u
#define CH_RESULT_PATH_BYTES 1146u
#define CH_RESULT_ENEMY_BYTES 39u
#define CH_RESULT_STACK_BYTES 12u
/* Read-only live state, with no instruction bytes or implied path read.
 * The same fields form the prefix of a complete snapshot. */
typedef struct {
    uint32_t abi,rom,wram,io,engine,counter;
    uint8_t enemy[CH_RESULT_ENEMY_BYTES];
    uint8_t temp_enemy,cur_level,battle_mode,temp_wild,trainer,battle_type;
    uint8_t link,tower,map[2],script[9];
    uint16_t applied_mask;
    /* script_fetch is the native selected-ROM-bank base, not a guest PC. */
    uint32_t script_cpu_pc,script_cpu_bank,script_fetch;
    uint32_t guest_sp;
    uint8_t generation_stack[CH_RESULT_STACK_BYTES]; /* only the live SP top */
} ChResultProgress;
typedef struct {
    uint32_t abi,rom,wram,io,engine,counter;
    uint8_t enemy[CH_RESULT_ENEMY_BYTES]; /* fixed WRAM bank1 D206..D22C */
    uint8_t temp_enemy,cur_level,battle_mode,temp_wild,trainer,battle_type;
    /* D437..D43F: mode, running, bank, next PC, stack size and first
       parent bank/PC. The original shrine showemote is a script call. */
    uint8_t link,tower,map[2],script[9];
    uint16_t applied_mask;
    uint32_t script_cpu_pc,script_cpu_bank,script_fetch;
    uint32_t guest_sp;
    uint8_t generation_stack[CH_RESULT_STACK_BYTES];
    uint8_t path[CH_RESULT_PATH_BYTES]; /* actual immutable instruction reads */
} ChResultSnapshot;
typedef struct {
    uint64_t epoch;
    uint8_t source_identity[32];
    ChResultSnapshot source;
} ChResultSource;
typedef struct {
    uint64_t epoch;
    uint8_t source_identity[32];
    uint32_t current_counter,previous_scan_counter,engine_entries;
    uint32_t previous_ordinary_supported,current_ordinary_supported;
    /* These are observed original marker mask receipts, not control requests.
       Release fields remain in the ABI as optional provenance. Generation
       observation does not require or certify them; the manual input-plan
       observer owns the strict press/hold/release certificate. */
    uint32_t raw_press_counter,effective_press_counter;
    uint32_t raw_release_counter,effective_release_counter;
    uint32_t press_marker,release_marker;
    uint16_t press_mask,release_mask;
    uint32_t press_observed,release_observed;
} ChResultFrameReceipt;
enum {
    CH_RESULT_PENDING=0,CH_RESULT_COMPLETE=1,CH_RESULT_READY=2,CH_RESULT_REJECTED=-1,
    CH_RESULT_BAD_SOURCE=1,CH_RESULT_BAD_PATH=2,CH_RESULT_BAD_IDENTITY=3,
    CH_RESULT_BAD_UNIT=4,CH_RESULT_BAD_SCENE=5,CH_RESULT_BAD_INPUT=6,
    CH_RESULT_BAD_MAPPING=7
};
typedef struct {
    uint32_t abi,status,reason,last_counter,observations;
    uint32_t press_observed,raw_press_counter,effective_press_counter,ready;
    /* Latched only from the checked original live post-generation chain. */
    uint32_t generation_observed,generation_counter,generated_dv;
    ChResultProgress ready_state;
    ChResultSource binding;
} ChResultGate;
typedef struct {
    uint32_t abi,counter,species,level,dv,complete,manual_hardware_verified;
    uint64_t epoch;
    uint8_t source_identity[32];
    ChResultSnapshot observed;
} ChResultObservation;

/* Read twice at an owned emulator boundary. No live read value is fabricated.
 * Failure leaves out zeroed. Ownership/quiescence must come from platform. */
int ch_result_read_snapshot(const ChReadOps *,ChResultSnapshot *);
int ch_result_read_progress(const ChReadOps *,ChResultProgress *);
int ch_result_begin(ChResultGate *,const ChResultSource *);
/* Observe each owned pre-HID callback. Before the original A receipt, require
 * the ordinary +1 chain. Latch A only from its checked raw/effective counters,
 * original marker mask and an ordinary scan at that effective counter.
 * After A, prediction support/marker count no longer governs data reads:
 * the actual counter may stay equal or advance in unsigned serial order.
 * READY additionally requires an observed original post-generation live call
 * chain, retained with its generated DV bytes on later frames. It never
 * publishes a DV or certifies a path read; call read_snapshot then complete
 * at the same owned boundary.
 * Read failures, source changes and real counter regressions must invalidate. */
int ch_result_observe_progress(ChResultGate *,const ChResultProgress *,
                               const ChResultFrameReceipt *);
/* Requires a READY progress record, the same live state, and a fresh full
 * pinned-path read. Only this call publishes an actual DV. */
int ch_result_complete(ChResultGate *,const ChResultSnapshot *,ChResultObservation *);
/* Full-snapshot convenience wrapper with the same admission/completion rules. */
int ch_result_observe(ChResultGate *,const ChResultSnapshot *,
                      const ChResultFrameReceipt *,ChResultObservation *);
void ch_result_invalidate(ChResultGate *,uint32_t reason);
uint32_t ch_result_snapshot_bytes(void);
uint32_t ch_result_progress_bytes(void);
uint32_t ch_result_gate_bytes(void);
uint32_t ch_result_receipt_bytes(void);
uint32_t ch_result_observation_bytes(void);
#endif
